import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { getDefaultRoute } from '../utils/auth';
import './AuthPage.css';

const demoAccounts = [
  {
    label: 'Student',
    email: process.env.REACT_APP_DEMO_STUDENT_EMAIL,
    password: process.env.REACT_APP_DEMO_STUDENT_PASSWORD,
  },
  {
    label: 'Admin',
    email: process.env.REACT_APP_DEMO_ADMIN_EMAIL,
    password: process.env.REACT_APP_DEMO_ADMIN_PASSWORD,
  },
].filter(account => account.email && account.password);

export default function LoginPage() {
  const [form, setForm] = useState({ email: '', password: '' });
  const [errors, setErrors] = useState({});
  const [apiError, setApiError] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const validate = () => {
    const nextErrors = {};
    if (!form.email.trim()) nextErrors.email = 'Email is required';
    else if (!/\S+@\S+\.\S+/.test(form.email)) nextErrors.email = 'Enter a valid email';
    if (!form.password) nextErrors.password = 'Password is required';
    return nextErrors;
  };

  const handleChange = (event) => {
    const { name, value } = event.target;
    setForm(previous => ({ ...previous, [name]: value }));
    setErrors(previous => ({ ...previous, [name]: '' }));
    setApiError('');
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    const nextErrors = validate();
    if (Object.keys(nextErrors).length) {
      setErrors(nextErrors);
      return;
    }

    setLoading(true);
    try {
      const loggedInUser = await login(form.email, form.password);
      navigate(getDefaultRoute(loggedInUser), { replace: true });
    } catch (error) {
      setApiError(error.message || 'Login failed. Please try again.');
    }
    setLoading(false);
  };

  return (
    <div className="auth-page">
      <div className="auth-left">
        <div className="auth-left-content">
          <Link to="/" className="auth-logo">
            <span role="img" aria-label="Graduation cap">🎓</span>
            <span>UniHelp</span>
          </Link>
          <blockquote className="auth-quote">
            "Empowering students with fast, transparent campus support."
          </blockquote>
          <div className="auth-decorative">
            <div className="deco-circle c1" />
            <div className="deco-circle c2" />
            <div className="deco-circle c3" />
          </div>
        </div>
      </div>

      <div className="auth-right">
        <div className="auth-form-container animate-fade-up">
          <div className="auth-form-header">
            <h1 className="auth-form-title">Welcome back</h1>
            <p className="auth-form-sub">Sign in to your UniHelp account</p>
          </div>

          {apiError && <div className="alert alert-error">{apiError}</div>}

          <form onSubmit={handleSubmit} noValidate>
            <div className="form-group">
              <label className="form-label">Email address</label>
              <input
                className={`form-input ${errors.email ? 'input-error' : ''}`}
                type="email"
                name="email"
                placeholder="your@email.edu"
                value={form.email}
                onChange={handleChange}
              />
              {errors.email && <span className="form-error">{errors.email}</span>}
            </div>

            <div className="form-group">
              <label className="form-label">Password</label>
              <input
                className={`form-input ${errors.password ? 'input-error' : ''}`}
                type="password"
                name="password"
                placeholder="Enter your password"
                value={form.password}
                onChange={handleChange}
              />
              {errors.password && <span className="form-error">{errors.password}</span>}
            </div>

            <button type="submit" className="btn btn-primary btn-block" disabled={loading}>
              {loading ? <span className="btn-spinner" /> : 'Sign In'}
            </button>
          </form>

          {demoAccounts.length > 0 && (
            <div className="auth-demo-hint">
              <strong>Development accounts:</strong><br />
              {demoAccounts.map(account => (
                <div key={account.label}>
                  {account.label}: {account.email} / {account.password}
                </div>
              ))}
            </div>
          )}

          <p className="auth-switch">
            Don't have an account? <Link to="/signup">Create one</Link>
          </p>
        </div>
      </div>
    </div>
  );
}
